function Write-EntraCAAuditLog{[CmdletBinding()]param([Parameter(Mandatory)][string]$Message,[string]$Component="General",[string]$LogRoot=(Join-Path $PSScriptRoot "../../Logs/Audit"));if(-not (Test-Path $LogRoot)){New-Item -ItemType Directory -Path $LogRoot -Force|Out-Null};$e=[PSCustomObject]@{Timestamp=(Get-Date).ToString("o");Component=$Component;Message=$Message;User="$env:USERNAME@$env:COMPUTERNAME"};$e|ConvertTo-Json -Compress|Add-Content -Path (Join-Path $LogRoot ("audit-{0}.log" -f (Get-Date -Format "yyyy-MM-dd"))) -Encoding UTF8}